#[derive(Debug, Clone)]
#[allow(non_camel_case_types)]
pub struct Systemd__SystemdRun {
    pub working_dir: Option<String>,

    pub dry_run: crate::dry_run::DryRunMode,
}

impl Systemd__SystemdRun {
    pub fn new(dry_run: crate::dry_run::DryRunMode) -> Self {
    Systemd__SystemdRun {
        working_dir: None,
        dry_run,
    }
}

pub async fn run_transient(&self, command_argv: Rc<Vec<String>>) -> std::result::Result<(bool, String, String), std::boxed::Box<dyn std::error::Error>> {
        if self.dry_run.is_dry_run() {
            eprintln!("[dry-run] RunTransient");
let json_body: serde_json::Value = serde_json::from_str(r#"{"success": true, "stdout": "Running as unit: demo.service", "stderr": ""}"#)?;
let success = json_body.pointer("/exit_success").and_then(|v| v.as_bool()).ok_or("missing field: exit_success")?;
let stdout = json_body.pointer("/stdout").and_then(|v| v.as_str()).map(|s| s.to_string()).ok_or("missing field: stdout")?;
let stderr = json_body.pointer("/stderr").and_then(|v| v.as_str()).map(|s| s.to_string()).ok_or("missing field: stderr")?;
Ok((success, stdout, stderr))
} else {
            let output = std::process::Command::new("systemd-run")
    .args(command_argv.clone().iter())
    .current_dir(self.working_dir.as_deref().unwrap_or("."))
    .output()?;
let stdout = String::from_utf8_lossy(&output.stdout).to_string();
let exit_code = output.status.code().unwrap_or(-1);
match exit_code {
    0 => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();
Ok((output.status.success(), stdout.clone(), stderr.clone())) },
    _ => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();  Err(stderr.into()) },
}
}
}

pub async fn run_transient_and_wait(&self, command_argv: Rc<Vec<String>>) -> std::result::Result<(i64, String, String), std::boxed::Box<dyn std::error::Error>> {
        if self.dry_run.is_dry_run() {
            eprintln!("[dry-run] RunTransientAndWait");
panic!("no mock data available for dry-run operation: RunTransientAndWait")
} else {
            let output = std::process::Command::new("systemd-run")
    .args(command_argv.clone().iter())
    .current_dir(self.working_dir.as_deref().unwrap_or("."))
    .output()?;
let stdout = String::from_utf8_lossy(&output.stdout).to_string();
let exit_code = output.status.code().unwrap_or(-1);
match exit_code {
    0 => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();
Ok(((output.status.code().unwrap_or(-1) as i64), stdout.clone(), stderr.clone())) },
    _ => { let stderr = String::from_utf8_lossy(&output.stderr).to_string();
Ok(((output.status.code().unwrap_or(-1) as i64), stdout.clone(), stderr.clone())) },
}
}
}
}

