pub fn grounded_summary_format_majors() -> Rc<Vec<i64>> {
    thread_local! {
        static CACHED: Rc<Vec<i64>> = {
            Rc::new(vec![255])
        };
    }
    CACHED.with(|c: &Rc<Vec<i64>>| c.clone())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum SummaryFormatStanding {
    SummaryFormatGrounded {
        major: i64,
    },
    SummaryFormatUngroundedMajor {
        major: i64,
    },
    SummaryFormatVersionUnreadable {
        line: String,
    },
}

pub fn summary_format_standing(version_line: String) -> Rc<SummaryFormatStanding> {
    match crate::extdeps_systemd_systemctl::systemd_major_version(version_line.clone()) {
    std::option::Option::None => Rc::new(SummaryFormatStanding::SummaryFormatVersionUnreadable {
    line: v1_rt::trim(version_line.clone()),
}),
    Some(v) => if grounded_summary_format_majors().iter().cloned().fold(false, |acc: bool, g: i64| (acc || (g.clone() == v.clone()))) {
        Rc::new(SummaryFormatStanding::SummaryFormatGrounded {
    major: v.clone(),
})
    } else {
        Rc::new(SummaryFormatStanding::SummaryFormatUngroundedMajor {
    major: v.clone(),
})
    },
}
}

pub fn summary_format_grounding_remedy() -> String {
    thread_local! {
        static CACHED: String = {
            "to ground it: read src/run/run.c and src/basic/format-util.h at that major and confirm four things -- the `if (arg_wait && !arg_quiet)` guard, the `Memory peak: %s` emit and its UINT64_MAX condition, that FORMAT_BYTES still passes USE_IEC | BELOW_POINT | TRAILING_B (SI vs IEC is ~7% and silent), and the line order -- then add the major to grounded_summary_format_majors".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn summary_format_standing_wire(s: Rc<SummaryFormatStanding>) -> String {
    match (*s.clone()).clone() {
    SummaryFormatStanding::SummaryFormatGrounded { major: major, .. } => Rc::new(vec!["systemd ".to_string(), (major.clone()).to_string(), ", a major this module has read".to_string()]).join(&"".to_string()),
    SummaryFormatStanding::SummaryFormatUngroundedMajor { major: major, .. } => Rc::new(vec!["systemd ".to_string(), (major.clone()).to_string(), " is outside the majors whose summary format this module has read, so its figures are not interpretable here; ".to_string(), summary_format_grounding_remedy()]).join(&"".to_string()),
    SummaryFormatStanding::SummaryFormatVersionUnreadable { line: line, .. } => Rc::new(vec!["the manager's version line did not parse (".to_string(), line.clone(), "), so the summary format is unknown; establish the major first (systemd-run --version opens \"systemd <MAJOR>\"), then ".to_string(), summary_format_grounding_remedy()]).join(&"".to_string()),
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum SystemdServiceResultReading {
    ServiceResultRead {
        result: SystemdServiceResult,
    },
    ServiceResultUnrecognized {
        wire: String,
    },
    ServiceResultNotReported {
        absence: SummaryAbsence,
    },
    ServiceResultFormatNotGrounded {
        standing: Rc<SummaryFormatStanding>,
    },
}

pub fn systemd_service_result_parse(wire: String) -> Rc<SystemdServiceResultReading> {
    {
        let w = v1_rt::trim(wire);
if (w.clone() == "success".to_string()) {
            Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultSuccess,
})
        } else {
            if (w.clone() == "protocol".to_string()) {
                Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultProtocol,
})
            } else {
                if (w.clone() == "timeout".to_string()) {
                    Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultTimeout,
})
                } else {
                    if (w.clone() == "exit-code".to_string()) {
                        Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultExitCode,
})
                    } else {
                        if (w.clone() == "signal".to_string()) {
                            Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultSignal,
})
                        } else {
                            if (w.clone() == "core-dump".to_string()) {
                                Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultCoreDump,
})
                            } else {
                                if (w.clone() == "watchdog".to_string()) {
                                    Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultWatchdog,
})
                                } else {
                                    if (w.clone() == "start-limit-hit".to_string()) {
                                        Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultStartLimitHit,
})
                                    } else {
                                        if (w.clone() == "resources".to_string()) {
                                            Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultResources,
})
                                        } else {
                                            if (w.clone() == "oom-kill".to_string()) {
                                                Rc::new(SystemdServiceResultReading::ServiceResultRead {
    result: SystemdServiceResult::ServiceResultOomKill,
})
                                            } else {
                                                Rc::new(SystemdServiceResultReading::ServiceResultUnrecognized {
    wire: w.clone(),
})
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum SystemdFormattedBytes {
    FormattedBytesExact {
        bytes: ByteSize,
    },
    FormattedBytesBounded {
        printed: String,
        lower: ByteSize,
        upper: ByteSize,
    },
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum SystemdFormattedBytesReading {
    FormattedBytesRead {
        value: Rc<SystemdFormattedBytes>,
    },
    FormattedBytesUnparseable {
        text: String,
    },
}

pub fn systemd_iec_suffix_factor(suffix: String) -> Option<Nat> {
    if (suffix.clone() == "K".to_string()) {
        Some(1024)
    } else {
        if (suffix.clone() == "M".to_string()) {
            Some(1048576)
        } else {
            if (suffix.clone() == "G".to_string()) {
                Some(1073741824)
            } else {
                if (suffix.clone() == "T".to_string()) {
                    Some(1099511627776)
                } else {
                    if (suffix.clone() == "P".to_string()) {
                        Some(1125899906842624)
                    } else {
                        if (suffix.clone() == "E".to_string()) {
                            Some(1152921504606846976)
                        } else {
                            std::option::Option::None
                        }
                    }
                }
            }
        }
    }
}

pub fn systemd_formatted_bytes_parse(text: String) -> Rc<SystemdFormattedBytesReading> {
    {
        let t = v1_rt::trim(text);
let n = v1_rt::string_length(&t);
if (n.clone() < 2) {
            Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
})
        } else {
            {
                let suffix = v1_rt::substring(&t, v1_rt::int_sub(n.clone(), 1), n.clone());
let body = v1_rt::substring(&t, 0, v1_rt::int_sub(n.clone(), 1));
if (suffix.clone() == "B".to_string()) {
                    match v1_rt::parse_int(body.clone()) {
    Some(v) => if (v.clone() < 0) {
                        Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
})
                    } else {
                        Rc::new(SystemdFormattedBytesReading::FormattedBytesRead {
    value: Rc::new(SystemdFormattedBytes::FormattedBytesExact {
    bytes: crate::std_measure::byte_size(v.clone()),
}),
})
                    },
    std::option::Option::None => Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
}),
}
                } else {
                    match systemd_iec_suffix_factor(suffix.clone()) {
    std::option::Option::None => Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
}),
    Some(factor) => { let __fm = Rc::new(body.clone().split(&".".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()); if __fm.len() >= 1 { let whole_text = (*__fm)[0].clone(); let rest: Rc<Vec<_>> = Rc::new(__fm.skip(1)); { let __fm = rest.clone(); if __fm.len() >= 1 { let tenth_text = (*__fm)[0].clone(); let more: Rc<Vec<_>> = Rc::new(__fm.skip(1)); { let __fm = more.clone(); if __fm.len() >= 1 { Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
}) } else { match v1_rt::parse_int(whole_text.clone()) {
    std::option::Option::None => Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
}),
    Some(w) => match v1_rt::parse_int(tenth_text.clone()) {
    std::option::Option::None => Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
}),
    Some(d) => if ((((w.clone() < 0) || (d.clone() < 0)) || (d.clone() > 9)) || (v1_rt::string_length(&tenth_text) != 1)) {
                        Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
})
                    } else {
                        Rc::new(SystemdFormattedBytesReading::FormattedBytesRead {
    value: Rc::new(SystemdFormattedBytes::FormattedBytesBounded {
    printed: t.clone(),
    lower: crate::std_measure::byte_size(v1_rt::int_div(v1_rt::int_mul(v1_rt::int_add(v1_rt::int_mul(w.clone(), 10), d.clone()), factor.clone()), 10)),
    upper: crate::std_measure::byte_size(v1_rt::int_div(v1_rt::int_add(v1_rt::int_mul(v1_rt::int_add(v1_rt::int_add(v1_rt::int_mul(w.clone(), 10), d.clone()), 2), factor.clone()), 9), 10)),
}),
})
                    },
},
} } } } else { Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
}) } } } else { Rc::new(SystemdFormattedBytesReading::FormattedBytesUnparseable {
    text: t.clone(),
}) } },
}
                }
}
        }
}
}

pub fn systemd_formatted_bytes_upper(b: Rc<SystemdFormattedBytes>) -> ByteSize {
    match (*b.clone()).clone() {
    SystemdFormattedBytes::FormattedBytesExact { bytes: bytes, .. } => bytes.clone(),
    SystemdFormattedBytes::FormattedBytesBounded { upper, .. } => upper.clone(),
}
}

