#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct SystemdRunWaitSummary {
    pub result: Rc<SystemdServiceResultReading>,
    pub memory_peak: Rc<SystemdMemoryPeakReading>,
}

pub fn systemd_run_summary_result_prefix() -> String {
    thread_local! {
        static CACHED: String = {
            "Finished with result: ".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn systemd_run_summary_memory_peak_prefix() -> String {
    thread_local! {
        static CACHED: String = {
            "Memory peak: ".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn systemd_run_summary_last_value(stderr: String, prefix: String) -> Option<String> {
    Rc::new(stderr.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned().fold(std::option::Option::None, |acc: _, line: String| if v1_rt::starts_with(line.clone(), prefix.clone()) {
        Some(v1_rt::substring(&line, v1_rt::string_length(&prefix), v1_rt::string_length(&line)))
    } else {
        acc.clone()
    })
}

pub fn systemd_argv_suppresses_summary(argv: Rc<Vec<String>>) -> bool {
    argv.iter().cloned().fold(false, |acc: bool, w: String| (acc || (w.clone() == "--quiet".to_string())))
}

pub fn systemd_run_wait_summary(launcher: Rc<SystemdSummaryPrintingWait>, standing: Rc<SummaryFormatStanding>, stderr: String) -> Rc<SystemdRunWaitSummary> {
    match (*standing.clone()).clone() {
    SummaryFormatStanding::SummaryFormatUngroundedMajor { major: _, .. } => Rc::new(SystemdRunWaitSummary {
    result: Rc::new(SystemdServiceResultReading::ServiceResultFormatNotGrounded {
    standing: standing.clone(),
}),
    memory_peak: Rc::new(SystemdMemoryPeakReading::MemoryPeakFormatNotGrounded {
    standing: standing.clone(),
}),
}),
    SummaryFormatStanding::SummaryFormatVersionUnreadable { line: _, .. } => Rc::new(SystemdRunWaitSummary {
    result: Rc::new(SystemdServiceResultReading::ServiceResultFormatNotGrounded {
    standing: standing.clone(),
}),
    memory_peak: Rc::new(SystemdMemoryPeakReading::MemoryPeakFormatNotGrounded {
    standing: standing.clone(),
}),
}),
    SummaryFormatStanding::SummaryFormatGrounded { major: _, .. } => systemd_run_grounded_wait_summary(launcher, stderr),
}
}

pub fn systemd_run_grounded_wait_summary(launcher: Rc<SystemdSummaryPrintingWait>, stderr: String) -> Rc<SystemdRunWaitSummary> {
    if systemd_argv_suppresses_summary(systemd_summary_printing_wait_argv(launcher)) {
        Rc::new(SystemdRunWaitSummary {
    result: Rc::new(SystemdServiceResultReading::ServiceResultNotReported {
    absence: SummaryAbsence::SummarySuppressedByQuietLauncher,
}),
    memory_peak: Rc::new(SystemdMemoryPeakReading::MemoryPeakNotReported {
    absence: SummaryAbsence::SummarySuppressedByQuietLauncher,
}),
})
    } else {
        Rc::new(SystemdRunWaitSummary {
    result: match systemd_run_summary_last_value(stderr.clone(), systemd_run_summary_result_prefix()) {
    Some(v) => systemd_service_result_parse(v.clone()),
    std::option::Option::None => Rc::new(SystemdServiceResultReading::ServiceResultNotReported {
    absence: if (stderr.clone() == "".to_string()) {
            SummaryAbsence::SummaryCaptureEmpty
        } else {
            SummaryAbsence::SummaryLineAbsent
        },
}),
},
    memory_peak: match systemd_run_summary_last_value(stderr.clone(), systemd_run_summary_memory_peak_prefix()) {
    Some(v) => match (*systemd_formatted_bytes_parse(v.clone())).clone() {
    SystemdFormattedBytesReading::FormattedBytesRead { value: b, .. } => Rc::new(SystemdMemoryPeakReading::MemoryPeakRead {
    peak: b.clone(),
}),
    SystemdFormattedBytesReading::FormattedBytesUnparseable { text: x, .. } => Rc::new(SystemdMemoryPeakReading::MemoryPeakUnparseable {
    text: x.clone(),
}),
},
    std::option::Option::None => Rc::new(SystemdMemoryPeakReading::MemoryPeakNotReported {
    absence: if (stderr.clone() == "".to_string()) {
            SummaryAbsence::SummaryCaptureEmpty
        } else {
            SummaryAbsence::SummaryLineAbsent
        },
}),
},
})
    }
}

